package com.specathon.customer.model;
import javax.persistence.Entity; import javax.persistence.Id;
@Entity public class Customer { @Id private Long id; private String name; private String email; public Long getId(){return id;} public void setId(Long v){id=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} }